// The built web UI compiled into the plug-in (generated by cmake/EmbedFiles.cmake).
#pragma once

#include <cstddef>
#include <string_view>

namespace plenio::webui
{

struct File
{
    const char* path;          // from "/", e.g. "/index.html"
    const unsigned char* data;
    std::size_t size;
    const char* mime;
};

const File* begin();
const File* end();

inline const File* find (std::string_view path)
{
    for (auto* f = begin(); f != end(); ++f)
        if (path == f->path)
            return f;
    return nullptr;
}

} // namespace plenio::webui
